#!/usr/bin/env bash
# Run from the root of your X-ReMap checkout, AFTER the earlier launch-fix patch.
# Adds the system-tray icon + snappier animations, then runs the tests.
set -euo pipefail
git rev-parse --show-toplevel >/dev/null 2>&1 || { echo "Run this inside your X-ReMap git checkout." >&2; exit 1; }
echo '' | base64 -d | gunzip | git apply --verbose && python3 -m unittest discover -s tests && echo ALL_APPLIED_AND_PASSING
